CREATE OR REPLACE FUNCTION public.nx_pgbg_smoke_value() RETURNS integer
LANGUAGE plpgsql AS $fn$
DECLARE
    answer integer;
BEGIN
    SELECT r.v INTO answer
      FROM pg_background_launch('SELECT 6 * 7') h,
           LATERAL pg_background_result(h.pid, h.cookie) AS r(v int);
    RETURN answer;
END
$fn$;

CREATE OR REPLACE FUNCTION public.nx_pgbg_smoke_worker_pid() RETURNS integer
LANGUAGE plpgsql AS $fn$
DECLARE
    worker integer;
BEGIN
    SELECT r.v INTO worker
      FROM pg_background_launch('SELECT pg_backend_pid()') h,
           LATERAL pg_background_result(h.pid, h.cookie) AS r(v int);
    RETURN worker;
END
$fn$;
